package com.jinloes.practice;
import java.util.Arrays; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: two sorted integer arrays, for example: [1, 2, 2, 3] [2, 2, 4]"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ", args).trim()); return; } assertThat(Solution.intersection(new int[]{1,2,2,3},new int[]{2,2,4})).containsExactly(2); assertThat(Solution.intersection(new int[]{1,3,5},new int[]{2,4,6})).isEmpty(); assertThat(Solution.intersection(new int[]{-3,-1,0,4},new int[]{-5,-3,0,2})).containsExactly(-3,0); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ int split=input.indexOf(']', input.indexOf('['))+1; int[] left=parse(input.substring(0,split)); int[] right=parse(input.substring(split)); System.out.println(Arrays.toString(Solution.intersection(left,right))); }catch(RuntimeException e){ System.out.println(USAGE); } } static int[] parse(String t){ String c=t.replace('[',' ').replace(']',' ').replace(',',' ').trim(); if(c.isEmpty()) return new int[0]; return Arrays.stream(c.split("\\s+")).mapToInt(Integer::parseInt).toArray(); } }
